import{c as n,$ as t,Q as l,j as d,o as i,g as r,m as u}from"./chunks/framework.Xjf2pjgg.js";const p="/assets/yurelic/screenshots/preview-01.png",g="/assets/yurelic/screenshots/preview-02.png",f="/assets/yurelic/screenshots/preview-03.png",h="/assets/yurelic/screenshots/preview-04.png",m="/assets/yurelic/screenshots/preview-05.png",y="/assets/yurelic/screenshots/preview-06.png",_="/assets/yurelic/screenshots/preview-07.png",b="/assets/yurelic/screenshots/preview-08.png",q="/assets/yurelic/screenshots/preview-09.png",P="/assets/yurelic/screenshots/preview-10.png",Y="/assets/yurelic/screenshots/preview-11.png",w="/assets/yurelic/screenshots/preview-12.png",v="/assets/yurelic/screenshots/preview-13.png",G=JSON.parse('{"title":"YuRelic 文档首页","description":"","frontmatter":{"title":"YuRelic 文档首页"},"headers":[],"relativePath":"plugins/items/yu-relic/index.md","filePath":"plugins/items/yu-relic/index.md"}'),x={name:"plugins/items/yu-relic/index.md"},k={class:"quick-actions"};function R(I,e,S,B,L,M){const a=t("PluginMeta"),s=t("CopyMarkdownButton"),o=t("CopyLLMButton"),c=t("PluginServerShowcase");return l(),d("div",null,[i(a,{slug:"yu-relic"}),r("div",k,[i(s,{page:""}),i(o,{page:""}),e[0]||(e[0]=r("a",{class:"tool-button",href:"https://qm.qq.com/q/xiwJYBYdh0",target:"_blank",rel:"noopener noreferrer"},"Yu 插件交流群",-1)),e[1]||(e[1]=r("a",{class:"tool-button primary",href:"https://www.afdian.com/item/0699c320541211f1b9e952540025c377",target:"_blank",rel:"noopener noreferrer"},"赞助付费版",-1))]),e[2]||(e[2]=u('<h2 id="版本与获取" tabindex="-1">版本与获取 <a class="header-anchor" href="#版本与获取" aria-label="Permalink to &quot;版本与获取&quot;">​</a></h2><p>YuRelic 当前文档以赞助版 <code>1.0.13.31</code> 的完整能力为主，同时保留免费版入门信息。你可以在 <a href="https://qm.qq.com/q/xiwJYBYdh0" target="_blank" rel="noreferrer">Yu 插件交流群</a> 获取免费版 YuRelic <code>1.0.0</code>；需要赞助付费版、持续更新或更完整玩法时，使用上方爱发电入口。</p><table tabindex="0"><thead><tr><th>版本</th><th>适合场景</th><th>获取方式</th></tr></thead><tbody><tr><td>免费版 <code>1.0.0</code></td><td>先在测试服验证开光、成长、基础灵器流程</td><td><a href="https://qm.qq.com/q/xiwJYBYdh0" target="_blank" rel="noreferrer">Yu 插件交流群</a></td></tr><tr><td>赞助版 <code>1.0.13.31</code></td><td>正式服、长期养成服、跨服或需要完整 GUI/诊断/生态能力</td><td><a href="https://www.afdian.com/item/0699c320541211f1b9e952540025c377" target="_blank" rel="noreferrer">爱发电赞助入口</a></td></tr></tbody></table><h2 id="环境速览" tabindex="-1">环境速览 <a class="header-anchor" href="#环境速览" aria-label="Permalink to &quot;环境速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前说明</th></tr></thead><tbody><tr><td>Minecraft</td><td><code>1.8.x - 1.26.x</code>，已测试 <code>1.21.1</code></td></tr><tr><td>Java</td><td><code>JDK 8</code> 及以上，构建产物保持 Java 8 字节码</td></tr><tr><td>服务端</td><td>Bukkit/Spigot/Paper/Paper衍生/Youer/Arclight/其余混合端等；模组混合端建议先用测试服采集物品识别规则</td></tr><tr><td>存储</td><td>单服默认 SQLite；跨服、天榜、防复制与软锁建议 MySQL</td></tr></tbody></table><h2 id="文档入口" tabindex="-1">文档入口 <a class="header-anchor" href="#文档入口" aria-label="Permalink to &quot;文档入口&quot;">​</a></h2><p>YuRelic 是面向 Minecraft 服务器的灵器成长 RPG 插件。它把武器、防具、工具、饰品等物品转化为可成长、可突破、可传承、可跨服追踪的灵器，并提供内建 GUI、掉落生态、诊断工具、PlaceholderAPI 与 Bukkit 事件接口。</p><div class="doc-card-grid"><a class="doc-mini-card" href="/plugins/items/yu-relic/install"><strong>安装部署</strong><span>环境要求、构建输出、动态依赖、首次启动和升级检查</span></a><a class="doc-mini-card" href="/plugins/items/yu-relic/gameplay"><strong>玩家玩法</strong><span>从开光到成长、突破、器魂、饰品、器藏与灵护的完整路线</span></a><a class="doc-mini-card" href="/plugins/items/yu-relic/commands"><strong>命令手册</strong><span>玩家、管理员、运维与开发调试命令按用途归类</span></a><a class="doc-mini-card" href="/plugins/items/yu-relic/config"><strong>配置说明</strong><span>模块化配置、存储、联动、经济、GUI、掉落和防复制</span></a><a class="doc-mini-card" href="/plugins/items/yu-relic/api"><strong>API 与权限</strong><span>权限节点、PlaceholderAPI、EasyBot、API 事件与集成建议</span></a><a class="doc-mini-card" href="/plugins/items/yu-relic/faq"><strong>常见问题</strong><span>不能开光、不长经验、依赖失败、数据库异常、重复 ID 等排障</span></a></div><h2 id="快速定位" tabindex="-1">快速定位 <a class="header-anchor" href="#快速定位" aria-label="Permalink to &quot;快速定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你想做什么</th><th>去哪里</th></tr></thead><tbody><tr><td>服主第一次安装、获取发布包或确认产物名</td><td><a href="/plugins/items/yu-relic/install">安装部署</a></td></tr><tr><td>玩家不知道先做什么、每个系统有什么用</td><td><a href="/plugins/items/yu-relic/gameplay">玩家玩法</a></td></tr><tr><td>查询某条 <code>/yurelic</code> 命令、别名或权限</td><td><a href="/plugins/items/yu-relic/commands">命令手册</a></td></tr><tr><td>调整开光成本、成长倍率、物品识别、跨服 MySQL、GUI</td><td><a href="/plugins/items/yu-relic/config">配置说明</a></td></tr><tr><td>接 PlaceholderAPI、EasyBot、监听 Bukkit 事件或分配权限</td><td><a href="/plugins/items/yu-relic/api">API 与权限</a></td></tr><tr><td>处理“不能开光”“不掉灵材”“PAPI 没值”“疑似复制”</td><td><a href="/plugins/items/yu-relic/faq">常见问题</a></td></tr></tbody></table><h2 id="当前版本定位" tabindex="-1">当前版本定位 <a class="header-anchor" href="#当前版本定位" aria-label="Permalink to &quot;当前版本定位&quot;">​</a></h2><ul><li>当前文档版本：<code>1.0.13.31</code>。YuRelic 为闭源插件，不提供从源码构建流程。</li><li>主命令：<code>/yurelic</code>，别名包含 <code>/yr</code>、<code>/yrelic</code>、<code>/relic</code>，并保留 <code>/yurpg</code>、<code>/yrpg</code> 作为迁移兼容。</li><li>配置入口：<code>plugins/YuRelic/config.yml</code>，实际默认配置拆分到 <code>configs/01-core.yml</code> 至 <code>configs/09-loot-integrity-scene.yml</code>。</li><li>数据原则：物品 NBT 是主真相源；SQLite/MySQL 用于跨服索引、审计、防复制、天榜和恢复辅助。</li><li>兼容策略：目标运行环境为 Minecraft <code>1.8.x - 1.26.x</code>、JDK 8 及以上；当前已测试环境为 <code>1.21.1</code>。</li></ul><h2 id="插件预览" tabindex="-1">插件预览 <a class="header-anchor" href="#插件预览" aria-label="Permalink to &quot;插件预览&quot;">​</a></h2><p>下面截图覆盖灵器 Lore、开光/养成 GUI、修复、掉落、天榜、器藏、诊断和玩法面板等常用场景，方便服主快速判断它是否适合自己的服务器节奏。</p><div class="yurelic-preview-grid"><figure><img src="'+p+'" alt="YuRelic 灵器 Lore 详情预览"><figcaption>灵器完整 Lore 与成长状态</figcaption></figure><figure><img src="'+g+'" alt="YuRelic GUI 预览 1"><figcaption>主菜单与核心入口</figcaption></figure><figure><img src="'+f+'" alt="YuRelic GUI 预览 2"><figcaption>开光与养成面板</figcaption></figure><figure><img src="'+h+'" alt="YuRelic 聊天展示预览"><figcaption>聊天展示与悬浮信息</figcaption></figure><figure><img src="'+m+'" alt="YuRelic 大屏截图预览"><figcaption>服务器实机使用场景</figcaption></figure><figure><img src="'+y+'" alt="YuRelic 修复界面预览"><figcaption>器体修复与资源投入</figcaption></figure><figure><img src="'+_+'" alt="YuRelic 天榜预览"><figcaption>天榜与器藏记录</figcaption></figure><figure><img src="'+b+'" alt="YuRelic 掉落预览"><figcaption>灵材掉落与生态反馈</figcaption></figure><figure><img src="'+q+'" alt="YuRelic 饰品预览"><figcaption>饰品槽与套装构筑</figcaption></figure><figure><img src="'+P+'" alt="YuRelic 诊断预览"><figcaption>Doctor 诊断与运维状态</figcaption></figure><figure><img src="'+Y+'" alt="YuRelic 商店预览"><figcaption>灵物坊与成本通道</figcaption></figure><figure><img src="'+w+'" alt="YuRelic 觉醒预览"><figcaption>觉醒、天赋与高阶成长</figcaption></figure><figure><img src="'+v+'" alt="YuRelic 管理预览"><figcaption>管理工具与配置辅助</figcaption></figure></div><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li>生存服：想让原版或模组装备拥有长期养成、修复、保值和展示价值。</li><li>RPG 服：需要成长路线、器魂、天赋、觉醒、掉落、战斗乘区和副本区域倍率。</li><li>群组服：需要跨服 MySQL、灵器软锁、审计、重复 ID 巡检和 STORAGE 天榜。</li><li>运维团队：需要 Doctor GUI、掉落模拟 GUI、动态依赖状态、配置版本检查和导出报告。</li><li>附属插件作者：需要事件、占位符、权限和低耦合集成点。</li></ul><h2 id="使用该插件的服务器" tabindex="-1">使用该插件的服务器 <a class="header-anchor" href="#使用该插件的服务器" aria-label="Permalink to &quot;使用该插件的服务器&quot;">​</a></h2>',18)),i(c,{slug:"yu-relic"})])}const U=n(x,[["render",R]]);export{G as __pageData,U as default};
